record Line(String account, long amount) {}
Map<String, Long> balance = new TreeMap<>();
List<List<Line>> journals = List.of(
    List.of(new Line("psp_receivable", 100_000), new Line("merchant_payable", -97_800), new Line("commission_revenue", -2_200)),
    List.of(new Line("bank", 98_500), new Line("psp_fee_expense", 1_500), new Line("psp_receivable", -100_000)),
    List.of(new Line("merchant_payable", 30_000), new Line("psp_receivable", -30_000)));
for (var j : journals)
    for (var l : j) balance.merge(l.account(), l.amount(), Long::sum);
System.out.println(balance.get("merchant_payable") + " " + balance.get("psp_receivable"));
